ALTER TABLE public.form_fields DISABLE TRIGGER form_fields_guard_answered;

UPDATE public.form_fields SET exemplo = 'Role 2d6 e some o atributo usado. Com 10 ou mais, a ação dá certo; de 7 a 9, dá certo, mas com um custo; com 6 ou menos, falha e o mestre complica a cena.' WHERE chave = 'motor' AND form_id = (SELECT id FROM public.forms WHERE slug = 'oficina-de-regras');
UPDATE public.form_fields SET exemplo = 'Só d6. Todo teste usa 2d6; vantagens acrescentam um terceiro dado, e o jogador fica com os dois maiores.' WHERE chave = 'dados' AND form_id = (SELECT id FROM public.forms WHERE slug = 'oficina-de-regras');
UPDATE public.form_fields SET exemplo = 'Três atributos: Força, Reflexo e Astúcia, com valores de −1 a +3.' WHERE chave = 'atributos' AND form_id = (SELECT id FROM public.forms WHERE slug = 'oficina-de-regras');
UPDATE public.form_fields SET exemplo = 'O valor do atributo é somado à rolagem: com Reflexo +2, pilotar no meio de uma tempestade é 2d6+2.' WHERE chave = 'funcao_atributos' AND form_id = (SELECT id FROM public.forms WHERE slug = 'oficina-de-regras');
UPDATE public.form_fields SET exemplo = 'Não há lista fixa. Cada personagem escreve três especialidades livres, como “cartografia celeste”; quando uma delas se aplica, o teste ganha vantagem.' WHERE chave = 'pericias' AND form_id = (SELECT id FROM public.forms WHERE slug = 'oficina-de-regras');
UPDATE public.form_fields SET exemplo = 'As faixas do teste são sempre as mesmas. Tarefas mais difíceis impõem −1 ou −2 na rolagem, e o mestre avisa antes de rolar.' WHERE chave = 'dificuldade' AND form_id = (SELECT id FROM public.forms WHERE slug = 'oficina-de-regras');
UPDATE public.form_fields SET exemplo = 'Não existe número de defesa. Quando é atacado, o personagem rola Reflexo: com 10 ou mais, escapa ileso; de 7 a 9, sofre metade do dano.' WHERE chave = 'defesa' AND form_id = (SELECT id FROM public.forms WHERE slug = 'oficina-de-regras');
UPDATE public.form_fields SET exemplo = 'Sem turnos fixos: o mestre passa a vez de personagem em personagem conforme a cena, e os inimigos agem quando alguém tira 9 ou menos.' WHERE chave = 'combate' AND form_id = (SELECT id FROM public.forms WHERE slug = 'oficina-de-regras');
UPDATE public.form_fields SET exemplo = 'Não há rolagem de iniciativa: quem provocou o confronto age primeiro, e depois a vez segue a ordem da mesa.' WHERE chave = 'iniciativa' AND form_id = (SELECT id FROM public.forms WHERE slug = 'oficina-de-regras');
UPDATE public.form_fields SET exemplo = 'Cada arma causa dano fixo: faca 1, pistola 2, canhão de convés 4. A armadura reduz o dano recebido em 1 ou 2.' WHERE chave = 'dano' AND form_id = (SELECT id FROM public.forms WHERE slug = 'oficina-de-regras');
UPDATE public.form_fields SET exemplo = 'Vida, com 6 marcações, e Fôlego, com 3 pontos que permitem rolar um teste de novo. O Fôlego volta inteiro após uma noite em terra firme.' WHERE chave = 'recursos' AND form_id = (SELECT id FROM public.forms WHERE slug = 'oficina-de-regras');
UPDATE public.form_fields SET exemplo = 'Cada poder tem nome, custo e efeito. Rajada: gaste 1 de Fôlego para empurrar um inimigo próximo para fora do convés.' WHERE chave = 'poderes' AND form_id = (SELECT id FROM public.forms WHERE slug = 'oficina-de-regras');
UPDATE public.form_fields SET exemplo = 'Três classes: Piloto, Mecânica e Navegadora. Cada uma começa com duas habilidades e ganha mais uma a cada avanço.' WHERE chave = 'classes' AND form_id = (SELECT id FROM public.forms WHERE slug = 'oficina-de-regras');
UPDATE public.form_fields SET exemplo = 'Ao fim de cada sessão, o personagem marca 1 de experiência se perseguiu seu objetivo pessoal. Com 5 marcas, ganha um avanço: +1 num atributo ou uma nova habilidade.' WHERE chave = 'progressao' AND form_id = (SELECT id FROM public.forms WHERE slug = 'oficina-de-regras');
UPDATE public.form_fields SET exemplo = 'Tirar 1 nos dois dados é um desastre: além de falhar, o personagem sofre uma consequência imediata, como perder o equipamento que estava usando.' WHERE chave = 'falhas_criticas' AND form_id = (SELECT id FROM public.forms WHERE slug = 'oficina-de-regras');
UPDATE public.form_fields SET exemplo = 'Voar acima das nuvens por muito tempo marca Frio. Com 3 marcas, os testes físicos sofrem −1 até o grupo descer e se aquecer.' WHERE chave = 'risco_adicional' AND form_id = (SELECT id FROM public.forms WHERE slug = 'oficina-de-regras');
UPDATE public.form_fields SET exemplo = 'Aventura de exploração e saque, em ritmo rápido, com decisões tomadas em grupo. O combate existe, mas é curto e perigoso.' WHERE chave = 'enfase' AND form_id = (SELECT id FROM public.forms WHERE slug = 'oficina-de-regras');

ALTER TABLE public.form_fields ENABLE TRIGGER form_fields_guard_answered;